def sha(b): return hashlib.sha256(b).hexdigest()
def tok(s):
 return {'placeholders':re.findall(r'\{[A-Za-z][A-Za-z0-9_]*\}',s),
         'markup':re.findall(r'</?[A-Za-z][^>]*>',s),
         'numbers':re.findall(r'(?<![A-Za-z])\d+(?:[.,]\d+)?%?(?![A-Za-z])',s),
         'protected':list(dict.fromkeys(re.findall(r'(?<![A-Za-z0-9])(?:[A-Z]{2,}[A-Z0-9]*|ffmpeg|Chromaprint|Soulseek|Spotify|YouTube|Pushbullet|Matrix|WebSocket|OpenAI)(?![A-Za-z0-9])',s)))}
source_rows=[json.loads(line) for line in (INPUT/'source-contexts.jsonl').read_text().splitlines()]
assert len(source_rows)==20 and len(TEXTS)==20
# This builder reads source/caller files only; it never opens current-target-cells.jsonl.
rows=[]
for i,src in enumerate(source_rows):
 key=src['sourceKey']; source_tokens=tok(key)
 assert len(TEXTS[i])==len(LOCALES)
 for locale,target in zip(LOCALES,TEXTS[i]):
  proposed_tokens=tok(target)
  manual=[t for t in ('ContentID','ID') if re.search(r'(?<![A-Za-z0-9])'+re.escape(t)+r'(?![A-Za-z0-9])',key)]
  manual_ok=all(re.search(r'(?<![A-Za-z0-9])'+re.escape(t)+r'(?![A-Za-z0-9])',target) for t in manual)
  valid=(source_tokens['placeholders']==proposed_tokens['placeholders'] and source_tokens['markup']==proposed_tokens['markup'] and source_tokens['numbers']==proposed_tokens['numbers'] and all(t in proposed_tokens['protected'] for t in source_tokens['protected']) and manual_ok)
  if not valid: raise SystemExit(f'token preservation failure: {src["position"]}/{locale}: {source_tokens} != {proposed_tokens}; manual={manual}')
  rows.append({'position':src['position'],'sourceKey':key,'sourceKeySha256':src['sourceKeySha256'],'sourceContextSha256':src['callerContextSha256'],'callerReferences':[{'path':c['path'],'line':c['line'],'lineSha256':c['lineSha256'],'contextSha256':c['contextSha256']} for c in src['callers']],'locale':locale,'proposedTarget':target,'proposedTargetSha256':sha(target.encode()),'sourceTokenSignature':source_tokens,'proposedTokenSignature':proposed_tokens,'protectedTermsRequired':manual,'tokenPreserved':True,'reviewBasis':'independent source/callsite interpretation; current target not consulted'})
assert len(rows)==240
(OUT/'independent-proposals.jsonl').write_text(''.join(json.dumps(r,ensure_ascii=False,separators=(',',':'))+'\n' for r in rows))
print(json.dumps({'result':'PASS','rows':len(rows),'locales':len(LOCALES),'sourceWindow':[1763,1782],'currentTranslationsRead':False,'sha256':sha((OUT/'independent-proposals.jsonl').read_bytes())},ensure_ascii=False,indent=2))
